import { SimpleDB } from "@nshiab/simple-data-analysis";
const sdb = new SimpleDB();
const table = sdb.newTable();
await table.loadData("./sales.csv");
const uniquePrices = await table.getUniques("price");
console.log(uniquePrices);
await sdb.done();
```

