// We create a new table
const table = sdb.newTable("geoTable");
// We load geospatial data from a file
await table.loadGeoData("./my-geodata.geojson");
// Reproject 'geomB' to match the projection of 'geomA'
await table.reproject("geomB", "EPSG:4326", "geomB_reprojected");
// Check if geometries in 'geomA' and 'geomB_reprojected' intersect
await table.intersect("geomA", "geomB_reprojected", "doIntersect");
// Log the first rows to see the results
await table.logTable();
// We close everything
await sdb.done();
```
