import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// Execute a query without returning data
await sdb.customQuery(
  "CREATE TABLE young_employees AS SELECT * FROM employees WHERE age > 30"
);
// We close everything
await sdb.done();
```

You can use `getColumns` to get the column headers. Here's an example:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load data into the table
await table.loadData("./data.csv");
// Get column headers
const headers = await table.getColumns();
console.log('Headers:', headers);
// Close everything
await sdb.done();
```
This will display all the headers from your CSV file.

Yes! You can use the `style` option to add custom CSS styling:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load geospatial data
await table.loadGeoData("./my-geodata.geojson");
// Define the map function with custom style
const mapFunction = (geoJsonData: { features: unknown[] }) =>
  plot({
    marks: [
      geo(geoJsonData, { stroke: "black", fill: "lightblue" }),
    ],
  });
// Save the map with custom style
await table.writeMap(mapFunction, "./output/map.png", {
  style: "background-color: #f0f0f0; padding: 20px;",
});
// We close everything
await sdb.done();
```

You can assign quantiles within categories using the `quantiles` method with the `categories` option. Here's an example:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
