const sdb = new SimpleDB();
// Create a new table
const table = sdb.newTable();
// Load data from a CSV file
await table.loadData("./data.csv");
// Assign deciles within each 'category' and store in 'quantiles'
await table.quantiles("column1", 10, "quantiles", { categories: "category" });
// Log the first rows to see the new column
await table.logTable();
// Close the database
await sdb.done();
```

