const sdb = new SimpleDB();
// Create left and right tables
const tableA = sdb.newTable("leftTable");
const tableB = sdb.newTable("rightTable");
// Load geospatial data into both tables
await tableA.loadGeoData("./left-geodata.geojson");
await tableB.loadGeoData("./right-geodata.geojson");
// Perform a within join using Haversine method with 10 km distance
await tableA.joinGeo(tableB, "within", {
  distance: 10,
  distanceMethod: "haversine",
  unit: "km"
});
// Log the joined results
await tableA.logTable();
// We close everything
await sdb.done();
```

