Here's how you can use AI to categorize names into 'Man', 'Woman', or 'Neutral':
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load sample data with names
await table.loadArray([
  { name: "Marie" },
  { name: "John" },
  { name: "Alex" },
]);
// Use AI to categorize each name into gender
await table.aiRowByRow(
  "name",
  "gender",
  `Guess whether it's a "Man" or a "Woman". If it could be both, return "Neutral".`,
  {
    cache: true,
    batchSize: 10,
    test: (dataPoint: unknown) => {
      if (
        typeof dataPoint !== "string" ||
        !['Man', 'Woman', 'Neutral'].includes(dataPoint)
      ) {
        throw new Error(`Invalid response: ${dataPoint}`);
      }
    },
    retry: 3,
    rateLimitPerMinute: 15,
    verbose: true,
  }
);
// Log the results
await table.logTable();
// We close everything
await sdb.done();
```

