import { SimpleDB } from "@nshiab/simple-data-analysis";
const sdb = new SimpleDB();
const table = sdb.newTable();
await table.loadData("./data.csv");
// Trim leading and trailing asterisks from 'productCode' and 'sku'
await table.trim(["productCode", "sku"], { character: "*" });
await table.logTable();
await sdb.done();
```

You can use the `batchSize` option to process multiple rows in each request:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load sample data into the table
await table.loadArray([
  { name: "Marie" },
  { name: "John" },
  { name: "Alex" },
]);
// Process multiple rows at once with batchSize
await table.aiRowByRow(
  "name",
  "gender",
  `Guess whether it's a "Man" or a "Woman". If it could be both, return "Neutral".`,
  {
    batchSize: 3, // Process all rows in one batch
  }
);
// Log the results
await table.logTable();
// We close everything
await sdb.done();
```

You can use the `getMean` method to compute the average of a numeric column. Here’s a straightforward example:
