  const modifiedRows = rows.map((d) => ({
    ...d,
    valueColumn: d.valueColumn > 100 ? d.valueColumn * 0.9 : d.valueColumn,
  }));
  return modifiedRows;
});
// Log the updated table
await table.logTable();
// We close everything
await sdb.done();
```

