import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load your data
await table.loadData("./data.csv");
// Remove duplicates based on all columns
await table.removeDuplicates();
// Log the cleaned table
await table.logTable();
// We close everything
await sdb.done();
```

Here's how you can disable coordinate rewinding for the map:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
import { geo, plot } from "@observablehq/plot";

const sdb = new SimpleDB();
const table = sdb.newTable();
await table.loadGeoData("./my-geodata.geojson");

const mapFunction = (geoJsonData: { features: unknown[] }) =>
  plot({
    projection: { type: "mercator", domain: geoJsonData },
    marks: [geo(geoJsonData, { fill: "lightblue" })],
  });

const outputPath = "./output/map-no-rewind.png";
// Disable coordinate rewinding
await table.writeMap(mapFunction, outputPath, { rewind: false });
await sdb.done();
```

