import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load some data
await table.loadArray([{ text: "Hello" }, { text: "World" }]);
// Use aiRowByRow to add a new column
await table.aiRowByRow(
  "text",
  "sentiment",
  "What is the sentiment of this text?",
  {
    cache: true,
  },
);
// Log the table to see the results
await table.logTable();
// We close everything
await sdb.done();
```

