You can use the `cache` option to cache the query embedding. Here's an example:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Load data into the table
await table.loadArray([
  { food: "pizza" },
  { food: "sushi" },
  { food: "burger" },
  { food: "pasta" },
  { food: "salad" },
  { food: "tacos" },
]);
// Generate embeddings for the "food" column and store in "embeddings" column
await table.aiEmbeddings("food", "embeddings", { cache: true });
// Find the 3 most similar foods to "italian food" and cache the query embedding
const similarFoods = await table.aiVectorSimilarity(
  "italian food",
  "embeddings",
  3,
  { cache: true }
);
