You can check and handle different types before updating:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// Initialize the database
const sdb = new SimpleDB();
// Create table and load data
const table = sdb.newTable();
await table.loadData("./data.csv");
// Safely modify 'column' based on its type
await table.updateWithJS((rows) => {
  const modifiedRows = rows.map((d) => {
    let newValue;
    if (typeof d.column === "number") {
      newValue = d.column * 2;
    } else if (typeof d.column === "string") {
      newValue = d.column.toUpperCase();
    } else {
      newValue = null;
    }
    return { ...d, column: newValue };
  });
  return modifiedRows;
});
// Log the changes
await table.logTable();
// Cleanup
await sdb.done();
```

