To create a dark-themed chart, you can use the `dark` option. Here's how:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable();
// Sample data
const data = [{ year: 2024, value: 10 }, { year: 2025, value: 15 }];
await table.loadArray(data);
// Define the chart function using Observable Plot
const chartFunction = (plotData: unknown[]) => {
  return plot({
    marks: [
      dot(plotData, { x: "year", y: "value" })
    ]
  });
};
// Enable dark mode for the chart
const darkOptions = {
  dark: true,
};
// Save the dark-themed chart as a PNG file
const outputPath = "output/dark-chart.png";
await table.writeChart(chartFunction, outputPath, darkOptions);
// Close everything
await sdb.done();
```

